      "rank": 3,
      "ballot_id": "B028",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks turned narrow optical transitions into exceptionally stable and accurate time standards, enabling precision tests of fundamental physics and a new generation of metrology.",
        "attribution": "Katori introduced the lattice clock concept and magic wavelength, while Ye drove major experimental realization and precision advances. The two-name attribution is unusually clear.",
        "maturity": "Independent groups have reproduced and advanced the technique, and its performance is well established. The clocks are already useful while continuing to improve.",
        "uncertainties": [
          "The boundary between the foundational invention and subsequent precision improvements could affect how the contribution is framed."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B012",
      "proposed_laureates": [
        "Antoine Browaeys",
        "Mikhail D. Lukin",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Rydberg blockade and programmable neutral-atom arrays provide a powerful, scalable way to control interacting quantum systems, with major contributions to quantum simulation and quantum information physics.",
        "attribution": "Zoller's theoretical work helped establish the blockade and simulation framework; Browaeys and Lukin led influential experimental programs demonstrating programmable arrays. Mark Saffman's contributions to the field also merit consideration.",
        "maturity": "The platform is reproducible across groups and has produced substantial many-body physics results. Large-scale, fault-tolerant computation remains under development.",
        "uncertainties": [
          "The candidate bundles the original blockade insight with later array technology and computing, whose credits are distributed across several groups."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B022",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Peter Zoller"
